import curses
import random

def main(stdscr):
    curses.curs_set(0)
    stdscr.timeout(120)
    curses.wrapper(stdscr.getmaxyx)

    def draw_snake(snake):
        for pos in snake:
            stdscr.addch(pos[0], pos[1], curses.ACS_CKBOARD)

    def draw_food(food):
        stdscr.addch(food[0], food[1], curses.ACS_PI)

    def draw_status(score):
        stdscr.addstr(0, 0, f"Score: {score}")

    def move_snake(snake, dr, dc):
        new_head = (snake[0][0] + dr, snake[0][1] + dc)
        if new_head in snake[1:]:
            return snake
        if new_head[0] < 0 or new_head[0] >= curses.wrapper(stdscr.getmaxyx)[0] or new_head[1] < 0 or new_head[1] >= curses.wrapper(stdscr.getmaxyx())[1]:
            return snake
        snake.insert(0, new_head)
        if new_head == food:
            food = (random.randint(1, curses.wrapper(stdscr.getmaxyx())[0] - 1), random.randint(1, curses.wrapper(stdscr.getmaxyx())[1] - 1))
        else:
            snake.pop()
        return snake

    def check_collision(snake):
        return snake[0] in snake[1:]

    def game_loop():
        snake = [(curses.wrapper(stdscr.getmaxyx())[0] // 2, curses.wrapper(stdscr.getmaxyx())[1] // 2)]
        food = (random.randint(1, curses.wrapper(stdscr.getmaxyx())[0] - 1), random.randint(1, curses.wrapper(stdscr.getmaxyx())[1] - 1))
        score = 0

        while True:
            draw_snake(snake)
            draw_food(food)
            draw_status(score)
            stdscr.refresh()

            key = stdscr.getch()
            if key == ord('q'):
                break
            dr, dc = (0, 0)
            if key == curses.KEY_UP:
                dr = -1
            elif key == curses.KEY_DOWN:
                dr = 1
            elif key == curses.KEY_LEFT:
                dc = -1
            elif key == curses.KEY_RIGHT:
                dc = 1
            snake = move_snake(snake, dr, dc)

            if check_collision(snake):
                stdscr.addstr(curses.wrapper(stdscr.getmaxyx())[0] // 2, curses.wrapper(stdscr.getmaxyx())[1] // 2, curses.ACS_PI)
                stdscr.refresh()
                break

    game_loop()

if __name__ == "__main__":
    curses.wrapper(main)
